{"path": "/app/bin/fees.py", "content": "#!/usr/bin/env python3
"""Overdue fee statements: python3 fees.py INPUT_DIR OUTPUT_FILE (see /app/docs)."""
import configparser
import csv
import datetime as dt
import json
import os
import re
import sys
from decimal import Decimal, ROUND_HALF_UP

ONE = dt.timedelta(days=1)
WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


# ---------------------------------------------------------------- helpers
def cents(text):
    return int((Decimal(str(text).strip()) * 100).quantize(Decimal(1), rounding=ROUND_HALF_UP))


def parse_date(s):
    return dt.date.fromisoformat(s.strip())


def patron_key(s):
    digits = re.sub(r"\D", "", str(s))
    return int(digits) if digits else None


def parse_offset(s):
    m = re.fullmatch(r"\s*([+-])(\d{1,2}):?(\d{2})?\s*", s)
    sign = -1 if m.group(1) == "-" else 1
    return sign * dt.timedelta(hours=int(m.group(2)), minutes=int(m.group(3) or 0))


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return [{(k or "").strip(): (v if v is not None else "") for k, v in row.items()}
                for row in csv.DictReader(f)]


# ---------------------------------------------------------------- policy
class Policy:
    def __init__(self, path):
        cp = configparser.RawConfigParser(interpolation=None)
        cp.optionxform = str
        with open(path, encoding="utf-8-sig") as f:
            cp.read_file(f)
        st = cp["statement"]
        self.library = st["library"].strip()
        self.start = parse_date(st["period_start"])
        self.end = parse_date(st["period_end"])
        self.base_offset = dt.timedelta(0)
        self.changes = []
        if cp.has_section("clock"):
            c = cp["clock"]
            self.base_offset = parse_offset(c.get("offset", "+00:00"))
            for part in c.get("changes", "").split(";"):
                part = part.strip()
                if not part:
                    continue
                inst, off = part.split()
                t = dt.datetime.strptime(inst, "%Y-%m-%dT%H:%MZ")
                self.changes.append((t, parse_offset(off)))
            self.changes.sort()
        self.items = {}      # lower -> dict
        self.categories = {}
        for sec in cp.sections():
            if sec.lower().startswith("item:"):
                name = sec[5:].strip()
                s = cp[sec]
                self.items[name.lower()] = {
                    "name": name,
                    "loan_days": int(s["loan_days"]),
                    "renewals": int(s["renewals"]),
                    "grace": int(s["grace_days"]),
                    "daily": cents(s["daily"]),
                    "loan_cap": cents(s["loan_cap"]),
                }
            elif sec.lower().startswith("category:"):
                name = sec[9:].strip()
                s = cp[sec]
                cap = s.get("statement_cap", "none").strip()
                self.categories[name.lower()] = {
                    "name": name,
                    "cap": None if cap.lower() == "none" or cap == "" else cents(cap),
                    "discount": int(Decimal(s.get("discount", "0").strip() or "0")),
                    "exempt": {x.strip().lower() for x in s.get("exempt", "").split(",") if x.strip()},
                }

    def offset_at(self, utc):
        off = self.base_offset
        for t, o in self.changes:
            if t <= utc:
                off = o
            else:
                break
        return off


# ---------------------------------------------------------------- calendar
class Calendar:
    def __init__(self, branches, rows):
        self.open_days = {}
        for b in branches:
            days = {d.strip().lower()[:3] for d in b["open_days"].split()}
            self.open_days[b["branch"].strip().upper()] = {WEEKDAYS.index(d) for d in days if d in WEEKDAYS}
        self.rows = {}  # branch upper or '*' -> list of (first, last, open)
        for r in rows:
            d = r["date"].strip()
            if ".." in d:
                a, b = d.split("..")
            else:
                a = b = d
            self.rows.setdefault(r["branch"].strip().upper() if r["branch"].strip() != "*" else "*", []).append(
                (parse_date(a), parse_date(b), r["status"].strip().lower() == "open"))
        self.cache = {}

    def _lookup(self, key, day):
        res = None
        for a, b, o in self.rows.get(key, ()):
            if a <= day <= b:
                res = o
        return res

    def is_open(self, branch, day):
        k = (branch, day)
        if k in self.cache:
            return self.cache[k]
        r = self._lookup(branch, day)
        if r is None:
            r = self._lookup("*", day)
        if r is None:
            r = day.weekday() in self.open_days.get(branch, ())
        self.cache[k] = r
        return r

    def next_open(self, branch, day):
        for _ in range(100000):
            if self.is_open(branch, day):
                return day
            day += ONE
        return day


# ---------------------------------------------------------------- events
def local_time(ev, policy):
    if "time" in ev and ev["time"] not in (None, ""):
        s = str(ev["time"]).strip().replace("T", " ")
        for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
            try:
                return dt.datetime.strptime(s, fmt)
            except ValueError:
                pass
        raise ValueError("bad time " + s)
    s = str(ev["at"]).strip()
    m = re.fullmatch(r"(\d{4}-\d\d-\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|z|[+-]\d\d:?\d\d)?", s)
    base = dt.datetime(int(m.group(1)[:4]), int(m.group(1)[5:7]), int(m.group(1)[8:10]),
                       int(m.group(2)), int(m.group(3)), int(m.group(4) or 0))
    z = m.group(5)
    off = dt.timedelta(0) if z in (None, "Z", "z") else parse_offset(z)
    utc = base - off
    return utc + policy.offset_at(utc)


def load_events(indir, policy):
    exdir = os.path.join(indir, "exports")
    events = {}
    for name in sorted(os.listdir(exdir)):
        if not (name.endswith(".csv") or name.endswith(".jsonl")):
            continue
        path = os.path.join(exdir, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            rows = read_csv(path)
        else:
            rows = []
            with open(path, encoding="utf-8-sig") as f:
                for line in f:
                    line = line.strip()
                    if line:
                        rows.append(json.loads(line))
        for r in rows:
            eid = str(r.get("event") or "").strip()
            if not eid or eid in events:
                continue
            def g(k):
                v = r.get(k)
                return "" if v is None else str(v).strip()
            events[eid] = {
                "event": eid,
                "type": g("type").lower(),
                "loan": g("loan"),
                "patron": g("patron"),
                "item": g("item"),
                "item_type": g("item_type"),
                "branch": g("branch").upper(),
                "via": g("via").lower(),
                "target": g("target"),
                "ltime": local_time(r, policy),
            }
    return events


# ---------------------------------------------------------------- main
def main(indir, outfile):
    policy = Policy(os.path.join(indir, "policy.ini"))
    branches = read_csv(os.path.join(indir, "branches.csv"))
    cal = Calendar(branches, read_csv(os.path.join(indir, "calendar.csv")))
    prow = read_csv(os.path.join(indir, "patrons.csv"))
    waivers = [w for w in read_csv(os.path.join(indir, "waivers.csv"))]

    patron_rows = {}
    for r in prow:
        patron_rows.setdefault(patron_key(r["patron"]), []).append(
            (parse_date(r["since"]), r["category"].strip(), r["patron"].strip()))
    for v in patron_rows.values():
        v.sort(key=lambda x: x[0])

    def patron_cat(pk, day):
        best = None
        for since, cat, label in patron_rows[pk]:
            if since <= day:
                best = (cat, label)
        if best is None:
            best = (patron_rows[pk][0][1], patron_rows[pk][0][2])
        return best

    events = load_events(indir, policy)
    cancelled = {e["target"] for e in events.values() if e["type"] == "void"}
    live = [e for e in events.values()
            if e["type"] != "void" and e["event"] not in cancelled]

    by_loan = {}
    checkouts = {}
    for e in live:
        if e["type"] == "checkout":
            checkouts.setdefault(e["loan"], e)
        elif e["type"] in ("renew", "return"):
            by_loan.setdefault(e["loan"], []).append(e)

    loans = []
    for lid, co in checkouts.items():
        cdate = co["ltime"].date()
        if cdate > policy.end:
            continue
        it = policy.items[co["item_type"].lower()]
        br = co["branch"]
        due = cal.next_open(br, cdate + dt.timedelta(days=it["loan_days"]))
        renewals = 0
        ret = None
        for e in sorted(by_loan.get(lid, []), key=lambda x: x["ltime"]):
            if e["type"] == "return":
                d = e["ltime"].date()
                ret = d - ONE if e["via"] == "dropbox" else d
                break
            d = e["ltime"].date()
            if d <= due and renewals < it["renewals"] and d <= policy.end:
                renewals += 1
                due = cal.next_open(br, d + dt.timedelta(days=it["loan_days"]))
        if ret is not None and ret > policy.end:
            ret = None  # still out at end of period
        if ret is not None and ret < policy.start:
            continue
        endday = ret if ret is not None else policy.end
        overdue = 0
        d = due + ONE
        while d <= endday:
            if cal.is_open(br, d):
                overdue += 1
            d += ONE
        if overdue == 0:
            continue
        charged = 0 if overdue <= it["grace"] else overdue
        pk = patron_key(co["patron"])
        ccat, _ = patron_cat(pk, cdate)
        cat = policy.categories[ccat.lower()]
        base = charged * it["daily"]
        if it["name"].lower() in cat["exempt"]:
            base = 0
        base = min(base, it["loan_cap"])
        assessed = (base * (100 - cat["discount"]) + 50) // 100
        loans.append({
            "loan": lid, "item": co["item"], "item_type": it["name"], "branch": br,
            "checkout": cdate, "due": due, "returned": ret,
            "overdue_days": overdue, "charged_days": charged, "assessed": assessed,
            "_patron": pk,
        })

    # waivers
    wv = {}
    for w in waivers:
        if w["status"].strip().lower() != "active":
            continue
        wv.setdefault(patron_key(w["patron"]), []).append(
            (w["loan"].strip(), w["value"].strip()))

    by_patron = {}
    for l in loans:
        by_patron.setdefault(l["_patron"], []).append(l)

    statements = []
    for pk in sorted(by_patron):
        ls = by_patron[pk]
        for l in ls:
            full = False
            total = 0
            for wl, val in wv.get(pk, ()):
                if wl != "*" and wl != l["loan"]:
                    continue
                if val.lower() == "full":
                    full = True
                else:
                    total += cents(val)
            l["waived"] = l["assessed"] if full else min(total, l["assessed"])
            l["net"] = l["assessed"] - l["waived"]
            l["capped"] = 0
        catname, label = patron_cat(pk, policy.end)
        cat = policy.categories[catname.lower()]
        if cat["cap"] is not None:
            excess = sum(l["net"] for l in ls) - cat["cap"]
            if excess > 0:
                # latest due first; ties: loan id sorting last first
                for l in sorted(ls, key=lambda x: (x["due"], x["loan"]), reverse=True):
                    if excess <= 0:
                        break
                    g = min(l["net"], excess)
                    l["capped"] = g
                    excess -= g
        for l in ls:
            l["billed"] = l["net"] - l["capped"]
        ls.sort(key=lambda x: (x["due"], x["loan"]))
        st = {"patron": label, "category": cat["name"], "loans": []}
        for l in ls:
            st["loans"].append({
                "loan": l["loan"], "item": l["item"], "item_type": l["item_type"],
                "branch": l["branch"], "checkout": l["checkout"].isoformat(),
                "due": l["due"].isoformat(),
                "returned": l["returned"].isoformat() if l["returned"] else None,
                "overdue_days": l["overdue_days"], "charged_days": l["charged_days"],
                "assessed": l["assessed"], "waived": l["waived"],
                "capped": l["capped"], "billed": l["billed"],
            })
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(x[k] for x in st["loans"])
        statements.append(st)

    summary = []
    for b in branches:
        bid = b["branch"].strip()
        row = {"branch": bid, "loans": 0, "charged_days": 0, "assessed": 0,
               "waived": 0, "capped": 0, "billed": 0}
        for st in statements:
            for l in st["loans"]:
                if l["branch"].upper() == bid.upper():
                    row["loans"] += 1
                    for k in ("charged_days", "assessed", "waived", "capped", "billed"):
                        row[k] += l[k]
        summary.append(row)

    out = {
        "library": policy.library,
        "period": {"start": policy.start.isoformat(), "end": policy.end.isoformat()},
        "statements": statements,
        "branches": summary,
    }
    odir = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(odir, exist_ok=True)
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
        f.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: fees.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
